// ContactUs.js
import React, { useState } from 'react';
import { Container, Row, Col, Form, Button, Alert } from 'react-bootstrap';
import './ContactUs.css';

const ContactUs = () => {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        subject: '',
        message: ''
    });
    const [showAlert, setShowAlert] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        // Simulação de envio
        setTimeout(() => {
            console.log('Dados do formulário:', formData);
            setIsSubmitting(false);
            setShowAlert(true);
            setFormData({
                name: '',
                email: '',
                subject: '',
                message: ''
            });

            setTimeout(() => setShowAlert(false), 5000);
        }, 1000);
    };

    return (
        <section id="contact" className="contact">
            <Container>
                <div className="section-title">
                    <h2>CONTATO</h2>
                    <p>Entre em contato comigo para discutir oportunidades, projetos ou colaborações.</p>
                </div>

                <Row className="justify-content-center">
                    {/* Formulário de Contato - Centralizado */}
                    <Col lg={8} className="d-flex align-items-stretch">
                        <Form onSubmit={handleSubmit} className="php-email-form">
                            {showAlert && (
                                <Alert variant="success" className="alert-success">
                                    <i className="bx bx-check-circle"></i>
                                    Sua mensagem foi enviada com sucesso! Obrigado.
                                </Alert>
                            )}

                            <Row>
                                <Col md={6} className="form-group">
                                    <Form.Label htmlFor="name">Sua Nome</Form.Label>
                                    <Form.Control
                                        type="text"
                                        name="name"
                                        id="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                        required
                                        placeholder="Digite seu nome completo"
                                    />
                                </Col>
                                <Col md={6} className="form-group mt-3 mt-md-0">
                                    <Form.Label htmlFor="email">Sua Email</Form.Label>
                                    <Form.Control
                                        type="email"
                                        name="email"
                                        id="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        required
                                        placeholder="seu.email@exemplo.com"
                                    />
                                </Col>
                            </Row>

                            <div className="form-group mt-3">
                                <Form.Label htmlFor="subject">Assunto</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="subject"
                                    id="subject"
                                    value={formData.subject}
                                    onChange={handleChange}
                                    required
                                    placeholder="Assunto da mensagem"
                                />
                            </div>

                            <div className="form-group mt-3">
                                <Form.Label htmlFor="message">Mensagem</Form.Label>
                                <Form.Control
                                    as="textarea"
                                    rows="6"
                                    name="message"
                                    id="message"
                                    value={formData.message}
                                    onChange={handleChange}
                                    required
                                    placeholder="Descreva sua mensagem aqui..."
                                />
                            </div>

                            <div className="text-center mt-4">
                                <Button
                                    type="submit"
                                    className="contact-btn"
                                    disabled={isSubmitting}
                                >
                                    {isSubmitting ? (
                                        <>
                                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                            Enviando...
                                        </>
                                    ) : (
                                        <>
                                            <i className="bx bx-send me-2"></i>
                                            Enviar Mensagem
                                        </>
                                    )}
                                </Button>
                            </div>
                        </Form>
                    </Col>
                </Row>
            </Container>
        </section>
    );
};

export default ContactUs;
